<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><p class="eyebrow"><a href="<?= site_url('admin/pesanan') ?>">Pesanan</a> / Detail</p><h1><?= esc($order['order_no']) ?></h1><?php if(session()->getFlashdata('error')): ?><p class="alert alert-error"><?= esc(session()->getFlashdata('error')) ?></p><?php endif ?><?php if(session()->getFlashdata('success')): ?><p class="alert alert-success"><?= esc(session()->getFlashdata('success')) ?></p><?php endif ?><div class="admin-order-grid"><section><h2>Detail pelanggan</h2><p><?= esc($order['customer_name']) ?> · <?= esc($order['customer_phone']) ?></p><p><?= esc($order['customer_email']) ?></p><p><?= $order['fulfillment_type']==='pickup'?'Ambil di toko':esc($order['address_snapshot'].' · '.$order['zone_name_snapshot']) ?></p><p><?= esc($order['pickup_date']) ?> · <?= esc($order['time_slot_snapshot']) ?></p><h2>Item pesanan</h2><?php foreach($items as $item): ?><p><?= (int)$item['quantity'] ?> × <?= esc($item['product_name_snapshot']) ?> · <?= esc($item['variant_name_snapshot']) ?> <strong>Rp<?= number_format((int)$item['line_total'],0,',','.') ?></strong><?php if($item['note']): ?><small>Catatan: <?= esc($item['note']) ?></small><?php endif ?></p><?php endforeach ?><p>Subtotal Rp<?= number_format((int)$order['subtotal'],0,',','.') ?></p><p>Ongkir Rp<?= number_format((int)$order['delivery_fee'],0,',','.') ?></p><p><strong>Total Rp<?= number_format((int)$order['total'],0,',','.') ?></strong></p></section><section><h2>Bukti pembayaran</h2><p>Periksa mutasi rekening. Gambar bukti saja bukan verifikasi pembayaran.</p><?php if($proofs===[]): ?><p>Belum ada bukti.</p><?php else: foreach($proofs as $proof): ?><article class="proof-review"><a href="<?= site_url('admin/pesanan/'.$order['id'].'/bukti/'.$proof['id']) ?>" target="_blank" rel="noopener">Lihat bukti · <?= esc($proof['status']) ?></a><?php if($proof['status']==='submitted' && $order['status']==='pending_payment'): ?><form method="post" action="<?= site_url('admin/pesanan/'.$order['id'].'/bukti/'.$proof['id']) ?>"><?= csrf_field() ?><button class="button" name="decision" value="accept">Terima pembayaran</button><label for="reason-<?= $proof['id'] ?>">Alasan penolakan</label><textarea id="reason-<?= $proof['id'] ?>" name="reason" rows="2"></textarea><button class="button button-secondary" name="decision" value="reject">Tolak bukti</button></form><?php endif ?></article><?php endforeach; endif ?><h2>Ubah status</h2><form method="post" action="<?= site_url('admin/pesanan/'.$order['id'].'/status') ?>"><?= csrf_field() ?><label for="status">Tahap berikutnya</label><select id="status" name="status"><option value="processing">Diproses</option><option value="ready_for_pickup">Siap Diambil</option><option value="out_for_delivery">Sedang Diantar</option><option value="completed">Selesai</option><option value="cancelled">Batalkan</option></select><label for="note">Catatan / alasan batal</label><textarea id="note" name="note" rows="2"></textarea><button class="button">Simpan status</button></form></section></div><section class="admin-section"><h2>Riwayat status</h2><ol class="timeline"><?php foreach($logs as $log): ?><li><strong><?= esc($log['to_status']) ?></strong><span><?= esc($log['created_at']) ?> · pelaku <?= $log['actor_id']===null?'sistem':'admin #'.(int)$log['actor_id'] ?></span><?php if($log['note']): ?><p><?= esc($log['note']) ?></p><?php endif ?></li><?php endforeach ?></ol></section><?= $this->endSection() ?>